            elif cy < pos[1]:
                dy = -1
        # If blocked by a wall at the next step, try to stay or adjust minimally
        next_x = pos[0] + dx
        next_y = pos[1] + dy
        blocked = False
        if isinstance(walls, list):
            if (next_x, next_y) in walls or not (0 <= next_x < 100 and 0 <= next_y < 100):
                blocked = True
        if blocked:
            # try alternative axis
            if dx != 0:
                alt_dx = 0
                alt_dy = 1 if dy >= 0 else -1
            else:
                alt_dx = 1 if dx >= 0 else -1
                alt_dy = 0
            # validate alt move
            nx = pos[0] + (alt_dx or 0)
            ny = pos[1] + (alt_dy or 0)
            if not ((nx, ny) in walls or not (0 <= nx < 100 and 0 <= ny < 100)):
                return [alt_dx, alt_dy]
            # else try to stay
            return [0, 0]
        return [dx, dy]

